from __future__ import annotations

"""
Built-in prebuilt dictionary data generated from your Excel files.

- Source: dataset_dictionary.xlsx (all parameters)
- Source: data_attribute_dictionary.xlsx (attribute templates by pool type)

This file is intentionally stored in a compressed form to keep repository size reasonable.
"""

import base64
import json
import zlib
from typing import Dict, List, Tuple


_PAYLOAD_B64 = ''


def _load() -> dict:
    data = base64.b64decode(_PAYLOAD_B64.encode("ascii"))
    raw = zlib.decompress(data)
    return json.loads(raw.decode("utf-8"))


def base_work_types() -> List[Dict]:
    return _load()["base_work_types"]


def category_items() -> List[Dict]:
    return _load()["categories"]


def pool_items() -> List[Dict]:
    return _load()["pools"]


def dataset_items() -> List[Dict]:
    return _load()["datasets"]


def attribute_templates() -> List[Tuple[str, Dict[str, str]]]:
    tmpl = _load()["attribute_templates"]
    return [(k, v) for k, v in tmpl.items()]
